#!/bin/sh
# Generate external/configs/microlinux_[kde_]<arch>_defconfig from
# external/configs/fragments/<arch>.config + common.config + lxqt.config or
# kde.config + repo.config.
# Edit the fragments, not the generated files. scripts/build.sh runs this.
set -e
C="$(dirname "$0")/../external/configs"
# editions: the LXQt one (microlinux_<arch>_defconfig) and the KDE one
# (microlinux_kde_<arch>_defconfig); each = arch + common + desktop + repo
for f in "$C"/fragments/*.config; do
	a=$(basename "$f" .config)
	case "$a" in common|repo|lxqt|kde|kde-packages) continue ;; esac
	for e in lxqt kde; do
		[ -f "$C/fragments/$e.config" ] || continue
		if [ $e = lxqt ]; then out=microlinux_${a}_defconfig; else out=microlinux_${e}_${a}_defconfig; fi
		{
			echo "# MicroLinux $a ($e edition) - Buildroot defconfig. GENERATED by scripts/gen-defconfigs.sh"
			echo "# from configs/fragments/{$a,common,$e,repo}.config: edit those."
			echo "# Build:  make BR2_EXTERNAL=<src>/external ${out} && make"
			echo
			cat "$f"
			echo
			cat "$C/fragments/common.config"
			echo
			cat "$C/fragments/$e.config"
			[ $e != kde ] || cat "$C/fragments/kde-packages.config" 2>/dev/null
			echo
			cat "$C/fragments/repo.config"
		} > "$C/$out.tmp"
		mv "$C/$out.tmp" "$C/$out"
	done
done
